test('bulk discount applies at 10 units', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  const bulkDiscount = Math.round(10000 * 2.5 / 100);
  assert.equal(totals.discount, bulkDiscount);
  assert.equal(totals.total, 10000 - bulkDiscount);
});

test('bulk discount does not apply at 9 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 9000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 9000);
});

test('bulk discount applies after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  const lineDiscount = Math.round(10000 * 10 / 100);
  const amountAfterLineDiscount = 10000 - lineDiscount;
  const bulkDiscount = Math.round(amountAfterLineDiscount * 2.5 / 100);
  assert.equal(totals.discount, lineDiscount + bulkDiscount);
  assert.equal(totals.total, 10000 - lineDiscount - bulkDiscount);
});

test('bulk discount with VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  const bulkDiscount = Math.round(10000 * 2.5 / 100);
  const amountAfterBulkDiscount = 10000 - bulkDiscount;
  const vat = Math.round(amountAfterBulkDiscount * 21 / 100);
  assert.equal(totals.discount, bulkDiscount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 10000 - bulkDiscount + vat);
});

test('bulk discount with line discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  const lineDiscount = Math.round(10000 * 5 / 100);
  const amountAfterLineDiscount = 10000 - lineDiscount;
  const bulkDiscount = Math.round(amountAfterLineDiscount * 2.5 / 100);
  const amountAfterBulkDiscount = amountAfterLineDiscount - bulkDiscount;
  const vat = Math.round(amountAfterBulkDiscount * 21 / 100);
  assert.equal(totals.discount, lineDiscount + bulkDiscount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 10000 - lineDiscount - bulkDiscount + vat);
});

