  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 15000);
  const bulkDiscountLine1 = Math.round(10000 * 2.5 / 100);
  assert.equal(totals.discount, bulkDiscountLine1);
  assert.equal(totals.total, 15000 - bulkDiscountLine1);
});

